import { createLogHost } from '@migaia/log-host'
import { defineOutputPlugin } from '@migaia/log-host/sdk'
import { reasoningPlugin } from '@migaia/log-plugin-reasoning'

// 流式片段写到这里；不传 write 时写到 stdout
const streamed: string[] = []
// 另一个输出代表审计日志，只收到每个阶段的完整文本
const audit = defineOutputPlugin({
  name: 'audit',
  batchable: false,
  defaultFormat: 'plain',
  deliver(records) {
    for (const { entry } of records) console.log(`审计记录 ${entry.tag}：${entry.message}`)
  }
})
const log = createLogHost({
  plugins: [reasoningPlugin({ write: (text) => streamed.push(text) }), audit]
})
log.startThinking()
log.thinking('先查库存，')
log.thinking('再算运费')
log.endThinking()
log.startResponse()
log.response('可以当天发货。')
log.endResponse()
await log.shutdown('manual')
console.log('流式写出的片段：', JSON.stringify(streamed))

import { createLogHost } from '@migaia/log-host'
import { reasoningPlugin } from '@migaia/log-plugin-reasoning'

/** 应用接收每次原样流式写入，保留片段边界。 */
const fragments: string[] = []
/** 明确开启 host 跟踪的异步流式调度。 */
const log = createLogHost({
  plugins: [
    reasoningPlugin({
      labels: { thinking: 'Plan', response: 'Answer' },
      asyncOutput: true,
      write: (text) => {
        fragments.push(text)
      }
    })
  ]
})
log.thinking('inspect')
log.response('ready')
log.endResponse()
await log.flush()
await log.shutdown('manual')

